<?php
require_once __DIR__.'/includes/functions.php';
if(!cart()){header('Location: cart.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$name=trim($_POST['full_name']??'');$phone=trim($_POST['phone']??'');$whatsapp=trim($_POST['whatsapp']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$address=trim($_POST['address']??'');$payment=in_array($_POST['payment']??'', ['Cash on Delivery','M-Pesa on confirmation'],true)?$_POST['payment']:'';
 if(!$name||!$phone||!$whatsapp||!$email||!$address||!$payment){flash('error','Please complete all checkout fields.');}
 else{try{
  $pdo=db();$pdo->beginTransaction();$ids=array_map('intval',array_keys(cart()));$marks=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT id,name,price,stock FROM products WHERE id IN ($marks) FOR UPDATE");$s->execute($ids);$products=[];foreach($s as $p)$products[(int)$p['id']]=$p;$total=0;
  foreach(cart() as $id=>$qty){$id=(int)$id;$qty=(int)$qty;if(empty($products[$id])||$qty<1||$qty>$products[$id]['stock'])throw new RuntimeException('One or more phones are no longer available in the requested quantity.');$total+=product_price($id,(float)$products[$id]['price'])*$qty;}
  $s=$pdo->prepare('INSERT INTO customers(full_name,phone,whatsapp,email,address) VALUES(?,?,?,?,?)');$s->execute([$name,$phone,$whatsapp,$email,$address]);$customer=(int)$pdo->lastInsertId();$number='CM-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$s=$pdo->prepare('INSERT INTO orders(order_number,customer_id,total,payment_method,status) VALUES(?,?,?,?,"Pending")');$s->execute([$number,$customer,$total,$payment]);$order=(int)$pdo->lastInsertId();$line=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,unit_price,quantity) VALUES(?,?,?,?,?)');$stock=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=? AND stock>=?');$check=$pdo->prepare('SELECT stock,name FROM products WHERE id=?');$threshold=max(1,(int)setting('low_stock_threshold','3'));
  foreach(cart() as $id=>$qty){$id=(int)$id;$qty=(int)$qty;$p=$products[$id];$unit=product_price($id,(float)$p['price']);$line->execute([$order,$id,$p['name'],$unit,$qty]);$stock->execute([$qty,$id,$qty]);if($stock->rowCount()!==1)throw new RuntimeException('Stock changed during checkout. Please try again.');$check->execute([$id]);$after=$check->fetch();if((int)$after['stock']<$threshold){$alert=$pdo->prepare('INSERT IGNORE INTO stock_alerts(product_id,last_quantity) VALUES(?,?)');$alert->execute([$id,$after['stock']]);if($alert->rowCount()===1){$to=getenv('COLLINS_M_ADMIN_EMAIL');$from=getenv('COLLINS_M_FROM_EMAIL');$headers=$from&&filter_var($from,FILTER_VALIDATE_EMAIL)?'From: Collins M <'.$from.'>':'';if($to&&filter_var($to,FILTER_VALIDATE_EMAIL)&&function_exists('mail')&&@mail($to,'Collins M low stock alert',$after['name'].' has '.$after['stock'].' unit(s) remaining.',$headers))$pdo->prepare('UPDATE stock_alerts SET notified_at=NOW() WHERE product_id=?')->execute([$id]);}else $pdo->prepare('UPDATE stock_alerts SET last_quantity=? WHERE product_id=?')->execute([$after['stock'],$id]);}else $pdo->prepare('DELETE FROM stock_alerts WHERE product_id=?')->execute([$id]);}
  $pdo->prepare('INSERT INTO order_status_history(order_id,old_status,new_status) VALUES(?,NULL,"Pending")')->execute([$order]);$pdo->commit();
  $from=getenv('COLLINS_M_FROM_EMAIL');if($from&&filter_var($from,FILTER_VALIDATE_EMAIL)){ $lines=[];foreach(cart() as $mailId=>$mailQty)$lines[]=$products[(int)$mailId]['name'].' × '.(int)$mailQty;$body="Thank you for your order.\n\nReference: ".$number."\nItems:\n - ".implode("\n - ",$lines)."\nTotal: KSh ".number_format($total,2)."\n\nWe will contact you to confirm delivery and payment.";@mail($email,'Collins M order '.$number.' received',$body,'From: Collins M <'.$from.'>'); }
  $_SESSION['cart']=[];$_SESSION['order_number']=$number;header('Location: order-confirmation.php');exit;
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();flash('error',$e instanceof RuntimeException?$e->getMessage():'We could not place the order. Please retry or contact Collins M.');}}
}
$page_title='Checkout';require 'includes/header.php';?>
<section class="section"><div class="container checkout"><p class="eyebrow">Secure checkout</p><h1>Delivery details</h1><p>Order total: <strong><?=money(cart_total())?></strong></p><form class="checkout-form" method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>Full name<input required name="full_name" maxlength="120"></label><label>Phone number<input required name="phone" maxlength="30"></label><label>WhatsApp number<input required name="whatsapp" maxlength="30"></label><label>Email<input required type="email" name="email" maxlength="190"></label><label>Delivery location / address<textarea required name="address" maxlength="1000"></textarea></label><label>Payment / delivery option<select name="payment"><option>Cash on Delivery</option><option>M-Pesa on confirmation</option></select></label><p class="bnpl-note">BNPL checkout is not connected. Available payment options above remain active.</p><button class="button primary">Place order</button></form></div></section><?php require 'includes/footer.php';?>
